package com.aoo.bcg.common.resource;
import static org.junit.jupiter.api.Assertions.*;import java.util.*;import org.junit.jupiter.api.Test;
class NativeMemoryBudgetTest{@Test void monitorsDirectCompressionTlsAndSdkAgainstCategoryAndTotalBudgets(){var limits=new EnumMap<NativeMemoryBudget.Category,Long>(NativeMemoryBudget.Category.class);for(var category:NativeMemoryBudget.Category.values())limits.put(category,100L);var budget=new NativeMemoryBudget(limits,250);try(var direct=budget.reserve(NativeMemoryBudget.Category.DIRECT_BUFFER,80);var tls=budget.reserve(NativeMemoryBudget.Category.TLS,90);var compression=budget.reserve(NativeMemoryBudget.Category.COMPRESSION,70)){assertEquals(240,budget.totalBytes());assertThrows(IllegalStateException.class,()->budget.reserve(NativeMemoryBudget.Category.NATIVE_SDK,20));assertEquals(90,budget.snapshot().get(NativeMemoryBudget.Category.TLS).highWatermarkBytes());}assertEquals(0,budget.totalBytes());assertEquals(90,budget.snapshot().get(NativeMemoryBudget.Category.TLS).highWatermarkBytes());}@Test void categoryLimitFailsBeforeAllocation(){var limits=new EnumMap<NativeMemoryBudget.Category,Long>(NativeMemoryBudget.Category.class);for(var category:NativeMemoryBudget.Category.values())limits.put(category,10L);var budget=new NativeMemoryBudget(limits,40);assertThrows(IllegalStateException.class,()->budget.reserve(NativeMemoryBudget.Category.DIRECT_BUFFER,11));}}
